import styled from '@emotion/styled';

export const Line = styled.hr`
  width: 100%;
  height: 0;
  border: none;
  border-top: 1px solid var(--ai-chat-color-divider, rgba(20, 20, 20, 0.1));
  margin: 0;
`;
